-- =====================================================================
-- PROYECTO: Sistema de Base de Datos Relacional - Clínica Médica San Rafael
-- FASE 2.1 : Creación de tablas y restricciones de integridad (DDL)
-- ARCHIVO  : 02_ddl_tablas.sql
-- EJECUTAR : conectado a la base "clinica_db"
-- =====================================================================
-- Convenciones:
--   * PK : columnas id_* con GENERATED BY DEFAULT AS IDENTITY
--   * FK : se declaran con nombre (fk_tabla_referencia) y con sus reglas
--          ON DELETE / ON UPDATE según las reglas de negocio (RN).
--   * CHECK, UNIQUE y NOT NULL llevan nombre para que los mensajes de
--     error indiquen exactamente qué regla se violó.
-- =====================================================================

-- El script es re-ejecutable: borra las tablas en orden inverso a sus
-- dependencias antes de crearlas de nuevo.
DROP TABLE IF EXISTS factura        CASCADE;
DROP TABLE IF EXISTS receta_detalle CASCADE;
DROP TABLE IF EXISTS consulta       CASCADE;
DROP TABLE IF EXISTS cita           CASCADE;
DROP TABLE IF EXISTS medicamento    CASCADE;
DROP TABLE IF EXISTS medico         CASCADE;
DROP TABLE IF EXISTS paciente       CASCADE;
DROP TABLE IF EXISTS consultorio    CASCADE;
DROP TABLE IF EXISTS aseguradora    CASCADE;
DROP TABLE IF EXISTS especialidad   CASCADE;

-- Descripción de la base de datos (se ejecuta aquí, y no en el archivo 01,
-- porque CREATE DATABASE debe ir sola).
COMMENT ON DATABASE clinica_db IS
    'Sistema de gestión de la Clínica Médica San Rafael: pacientes, médicos, citas, consultas, recetas y facturación.';

-- ---------------------------------------------------------------------
-- 1. ESPECIALIDAD: catálogo de especialidades médicas y su tarifa.
-- ---------------------------------------------------------------------
CREATE TABLE especialidad (
    id_especialidad  INTEGER       GENERATED BY DEFAULT AS IDENTITY,
    nombre           VARCHAR(60)   NOT NULL,
    descripcion      VARCHAR(200),
    tarifa_consulta  NUMERIC(10,2) NOT NULL,
    CONSTRAINT pk_especialidad        PRIMARY KEY (id_especialidad),
    CONSTRAINT uq_especialidad_nombre UNIQUE (nombre),
    CONSTRAINT ck_especialidad_tarifa CHECK (tarifa_consulta > 0)          -- RN11
);
COMMENT ON TABLE especialidad IS 'Especialidades médicas que ofrece la clínica y su tarifa de consulta.';

-- ---------------------------------------------------------------------
-- 2. ASEGURADORA: compañías de seguro con convenio.
-- ---------------------------------------------------------------------
CREATE TABLE aseguradora (
    id_aseguradora        INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    nombre                VARCHAR(80)  NOT NULL,
    telefono              VARCHAR(15)  NOT NULL,
    correo                VARCHAR(100),
    porcentaje_cobertura  NUMERIC(5,2) NOT NULL,
    CONSTRAINT pk_aseguradora          PRIMARY KEY (id_aseguradora),
    CONSTRAINT uq_aseguradora_nombre   UNIQUE (nombre),
    CONSTRAINT ck_aseguradora_cobertura
        CHECK (porcentaje_cobertura BETWEEN 0 AND 100)                     -- RN11
);
COMMENT ON TABLE aseguradora IS 'Aseguradoras con convenio y el porcentaje de la consulta que cubren.';

-- ---------------------------------------------------------------------
-- 3. CONSULTORIO: espacios físicos donde se atienden las citas.
-- ---------------------------------------------------------------------
CREATE TABLE consultorio (
    id_consultorio  INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    numero          VARCHAR(10)  NOT NULL,
    piso            SMALLINT     NOT NULL,
    equipamiento    VARCHAR(150),
    CONSTRAINT pk_consultorio        PRIMARY KEY (id_consultorio),
    CONSTRAINT uq_consultorio_numero UNIQUE (numero),
    CONSTRAINT ck_consultorio_piso   CHECK (piso BETWEEN 1 AND 10)
);
COMMENT ON TABLE consultorio IS 'Consultorios de la clínica.';

-- ---------------------------------------------------------------------
-- 4. PACIENTE
--    FK a aseguradora es opcional (paciente particular = NULL).
--    ON DELETE SET NULL: si la aseguradora se elimina, el paciente
--    queda como particular (RN04).
-- ---------------------------------------------------------------------
CREATE TABLE paciente (
    id_paciente       INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    cedula            VARCHAR(20)  NOT NULL,
    nombre            VARCHAR(50)  NOT NULL,
    apellido          VARCHAR(50)  NOT NULL,
    fecha_nacimiento  DATE         NOT NULL,
    sexo              CHAR(1)      NOT NULL,
    telefono          VARCHAR(15)  NOT NULL,
    correo            VARCHAR(100),
    direccion         VARCHAR(200),
    id_aseguradora    INTEGER,
    fecha_registro    DATE         NOT NULL DEFAULT CURRENT_DATE,
    CONSTRAINT pk_paciente         PRIMARY KEY (id_paciente),
    CONSTRAINT uq_paciente_cedula  UNIQUE (cedula),                         -- RN01
    CONSTRAINT uq_paciente_correo  UNIQUE (correo),
    CONSTRAINT ck_paciente_sexo    CHECK (sexo IN ('M', 'F')),
    CONSTRAINT ck_paciente_fnac    CHECK (fecha_nacimiento >= DATE '1900-01-01'),
    CONSTRAINT fk_paciente_aseguradora
        FOREIGN KEY (id_aseguradora) REFERENCES aseguradora (id_aseguradora)
        ON DELETE SET NULL                                                  -- RN04
        ON UPDATE CASCADE
);
COMMENT ON TABLE paciente IS 'Pacientes de la clínica; id_aseguradora NULL = paciente particular.';

-- ---------------------------------------------------------------------
-- 5. MEDICO
--    ON DELETE RESTRICT: no se elimina una especialidad con médicos (RN03).
--    ON UPDATE CASCADE : si cambia el código de la especialidad, se
--                        actualiza automáticamente en cada médico.
-- ---------------------------------------------------------------------
CREATE TABLE medico (
    id_medico        INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    cedula           VARCHAR(20)  NOT NULL,
    licencia         VARCHAR(20)  NOT NULL,
    nombre           VARCHAR(50)  NOT NULL,
    apellido         VARCHAR(50)  NOT NULL,
    telefono         VARCHAR(15)  NOT NULL,
    correo           VARCHAR(100) NOT NULL,
    id_especialidad  INTEGER      NOT NULL,
    fecha_ingreso    DATE         NOT NULL,
    activo           BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_medico           PRIMARY KEY (id_medico),
    CONSTRAINT uq_medico_cedula    UNIQUE (cedula),                         -- RN01
    CONSTRAINT uq_medico_licencia  UNIQUE (licencia),
    CONSTRAINT uq_medico_correo    UNIQUE (correo),
    CONSTRAINT fk_medico_especialidad
        FOREIGN KEY (id_especialidad) REFERENCES especialidad (id_especialidad)
        ON DELETE RESTRICT                                                  -- RN03
        ON UPDATE CASCADE
);
COMMENT ON TABLE medico IS 'Médicos de la clínica; cada uno pertenece a una especialidad (RN02).';

-- ---------------------------------------------------------------------
-- 6. MEDICAMENTO: inventario de la farmacia interna.
-- ---------------------------------------------------------------------
CREATE TABLE medicamento (
    id_medicamento   INTEGER       GENERATED BY DEFAULT AS IDENTITY,
    nombre           VARCHAR(80)   NOT NULL,
    presentacion     VARCHAR(60)   NOT NULL,
    precio_unitario  NUMERIC(10,2) NOT NULL,
    stock            INTEGER       NOT NULL DEFAULT 0,
    CONSTRAINT pk_medicamento        PRIMARY KEY (id_medicamento),
    CONSTRAINT uq_medicamento        UNIQUE (nombre, presentacion),
    CONSTRAINT ck_medicamento_precio CHECK (precio_unitario >= 0),          -- RN11
    CONSTRAINT ck_medicamento_stock  CHECK (stock >= 0)                     -- RN11
);
COMMENT ON TABLE medicamento IS 'Medicamentos disponibles, con precio y existencias.';

-- ---------------------------------------------------------------------
-- 7. CITA
--    Paciente y médico: ON DELETE RESTRICT (el historial se conserva, RN08).
--    Consultorio      : ON DELETE SET NULL (la cita queda por reubicar, RN10).
--    UNIQUE compuestos: impiden choques de horario (RN05).
-- ---------------------------------------------------------------------
CREATE TABLE cita (
    id_cita         INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    id_paciente     INTEGER      NOT NULL,
    id_medico       INTEGER      NOT NULL,
    id_consultorio  INTEGER,
    fecha_hora      TIMESTAMP    NOT NULL,
    motivo          VARCHAR(200) NOT NULL,
    estado          VARCHAR(15)  NOT NULL DEFAULT 'Programada',
    CONSTRAINT pk_cita PRIMARY KEY (id_cita),
    CONSTRAINT ck_cita_estado
        CHECK (estado IN ('Programada', 'Atendida', 'Cancelada', 'No asistió')),  -- RN06
    CONSTRAINT uq_cita_medico_horario      UNIQUE (id_medico, fecha_hora),       -- RN05
    CONSTRAINT uq_cita_consultorio_horario UNIQUE (id_consultorio, fecha_hora),  -- RN05
    CONSTRAINT fk_cita_paciente
        FOREIGN KEY (id_paciente) REFERENCES paciente (id_paciente)
        ON DELETE RESTRICT ON UPDATE CASCADE,                               -- RN08
    CONSTRAINT fk_cita_medico
        FOREIGN KEY (id_medico) REFERENCES medico (id_medico)
        ON DELETE RESTRICT ON UPDATE CASCADE,                               -- RN08
    CONSTRAINT fk_cita_consultorio
        FOREIGN KEY (id_consultorio) REFERENCES consultorio (id_consultorio)
        ON DELETE SET NULL ON UPDATE CASCADE                                -- RN10
);
COMMENT ON TABLE cita IS 'Citas agendadas: une paciente, médico y consultorio en una fecha y hora.';

-- ---------------------------------------------------------------------
-- 8. CONSULTA: resultado clínico de una cita atendida (relación 1:1).
--    UNIQUE (id_cita) convierte la relación 1:N en 1:1 (RN07).
--    La presión arterial se guarda en dos columnas atómicas (1FN).
-- ---------------------------------------------------------------------
CREATE TABLE consulta (
    id_consulta         INTEGER      GENERATED BY DEFAULT AS IDENTITY,
    id_cita             INTEGER      NOT NULL,
    presion_sistolica   SMALLINT,
    presion_diastolica  SMALLINT,
    temperatura         NUMERIC(4,1),
    peso_kg             NUMERIC(5,2),
    diagnostico         TEXT         NOT NULL,
    observaciones       TEXT,
    fecha_registro      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_consulta      PRIMARY KEY (id_consulta),
    CONSTRAINT uq_consulta_cita UNIQUE (id_cita),                           -- RN07
    CONSTRAINT ck_consulta_presion
        CHECK (presion_sistolica BETWEEN 50 AND 260
               AND presion_diastolica BETWEEN 30 AND 160),
    CONSTRAINT ck_consulta_temperatura CHECK (temperatura BETWEEN 30 AND 45),
    CONSTRAINT ck_consulta_peso        CHECK (peso_kg > 0),
    CONSTRAINT fk_consulta_cita
        FOREIGN KEY (id_cita) REFERENCES cita (id_cita)
        ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE consulta IS 'Datos clínicos registrados por el médico en una cita atendida.';

-- ---------------------------------------------------------------------
-- 9. RECETA_DETALLE: tabla intermedia N:M entre consulta y medicamento.
--    PK compuesta (id_consulta, id_medicamento).
--    ON DELETE CASCADE desde consulta (RN09); RESTRICT desde medicamento.
-- ---------------------------------------------------------------------
CREATE TABLE receta_detalle (
    id_consulta     INTEGER     NOT NULL,
    id_medicamento  INTEGER     NOT NULL,
    dosis           VARCHAR(50) NOT NULL,
    frecuencia      VARCHAR(50) NOT NULL,
    duracion_dias   SMALLINT    NOT NULL,
    cantidad        INTEGER     NOT NULL,
    CONSTRAINT pk_receta_detalle PRIMARY KEY (id_consulta, id_medicamento),
    CONSTRAINT ck_receta_duracion CHECK (duracion_dias > 0),
    CONSTRAINT ck_receta_cantidad CHECK (cantidad > 0),
    CONSTRAINT fk_receta_consulta
        FOREIGN KEY (id_consulta) REFERENCES consulta (id_consulta)
        ON DELETE CASCADE ON UPDATE CASCADE,                                -- RN09
    CONSTRAINT fk_receta_medicamento
        FOREIGN KEY (id_medicamento) REFERENCES medicamento (id_medicamento)
        ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE receta_detalle IS 'Medicamentos recetados en cada consulta, con su posología.';

-- ---------------------------------------------------------------------
-- 10. FACTURA: cobro de una cita atendida (relación 1:1 con cita).
--     monto_total guarda la tarifa vigente al facturar (RN13).
-- ---------------------------------------------------------------------
CREATE TABLE factura (
    id_factura      INTEGER       GENERATED BY DEFAULT AS IDENTITY,
    id_cita         INTEGER       NOT NULL,
    fecha_emision   DATE          NOT NULL DEFAULT CURRENT_DATE,
    monto_total     NUMERIC(10,2) NOT NULL,
    monto_cubierto  NUMERIC(10,2) NOT NULL DEFAULT 0,
    metodo_pago     VARCHAR(15),
    estado_pago     VARCHAR(10)   NOT NULL DEFAULT 'Pendiente',
    CONSTRAINT pk_factura       PRIMARY KEY (id_factura),
    CONSTRAINT uq_factura_cita  UNIQUE (id_cita),                           -- RN07
    CONSTRAINT ck_factura_montos
        CHECK (monto_total >= 0 AND monto_cubierto >= 0
               AND monto_cubierto <= monto_total),                          -- RN12
    CONSTRAINT ck_factura_metodo
        CHECK (metodo_pago IN ('Efectivo', 'Tarjeta', 'Transferencia', 'Yappy')),
    CONSTRAINT ck_factura_estado
        CHECK (estado_pago IN ('Pendiente', 'Pagada', 'Anulada')),
    CONSTRAINT ck_factura_pagada_con_metodo
        CHECK (estado_pago <> 'Pagada' OR metodo_pago IS NOT NULL),
    CONSTRAINT fk_factura_cita
        FOREIGN KEY (id_cita) REFERENCES cita (id_cita)
        ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE factura IS 'Facturas de citas atendidas; el paciente paga monto_total - monto_cubierto.';

-- ---------------------------------------------------------------------
-- Verificación: lista las tablas creadas y sus restricciones.
-- ---------------------------------------------------------------------
SELECT table_name
FROM   information_schema.tables
WHERE  table_schema = 'public'
ORDER  BY table_name;

SELECT tc.table_name,
       tc.constraint_name,
       tc.constraint_type,
       rc.delete_rule,
       rc.update_rule
FROM   information_schema.table_constraints tc
LEFT   JOIN information_schema.referential_constraints rc
       ON rc.constraint_name = tc.constraint_name
WHERE  tc.table_schema = 'public'
  AND  tc.constraint_type IN ('PRIMARY KEY', 'FOREIGN KEY', 'UNIQUE', 'CHECK')
  AND  tc.constraint_name NOT LIKE '%_not_null'
ORDER  BY tc.table_name, tc.constraint_type, tc.constraint_name;
